package com.bank.reference;

import java.util.logging.*;

public class RotatedSearchDemo {
    private static final Logger log = Logger.getLogger(RotatedSearchDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Sorted reference numbers rotated at an offset
        int[] refs = {40, 50, 60, 70, 10, 20, 30};

        ReferenceLocator locator = new ReferenceLocator();

        log.info("Searching for reference 20 (present)");
        log.info("Index -> " + locator.search(refs, 20));

        log.info("Searching for reference 55 (absent)");
        log.info("Index -> " + locator.search(refs, 55));
    }
}

