class ReferenceLocator {
    // Modified binary search over a rotated sorted array. O(log n), O(1).
    int search(int[] arr, int target) {
        int low = 0, high = arr.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;   // overflow-safe
            if (arr[mid] == target) return mid;

            if (arr[low] <= arr[mid]) {
                // Left half [low..mid] is sorted
                if (arr[low] <= target && target < arr[mid]) {
                    high = mid - 1;             // target in sorted left
                } else {
                    low = mid + 1;              // target in the other half
                }
            } else {
                // Right half [mid..high] is sorted
                if (arr[mid] < target && target <= arr[high]) {
                    low = mid + 1;              // target in sorted right
                } else {
                    high = mid - 1;             // target in the other half
                }
            }
        }
        return -1;  // not present
    }
}

